import { useStoreState } from "@ariakit/react-store";
import {
  useBooleanEvent,
  useEvent,
  useMergeRefs,
  useSafeLayoutEffect,
  useTransactionState,
  useWrapElement,
  createElement,
  createHook,
  forwardRef,
  memo,
} from "@ariakit/react-utils";
import type { Props } from "@ariakit/react-utils";
import {
  flatten2DArray,
  reverseArray,
  getActiveElement,
  isTextField,
  fireBlurEvent,
  fireKeyboardEvent,
  isSelfTarget,
  hasFocus,
  invariant,
  isFocusable,
} from "@ariakit/utils";
import type { BooleanOrCallback } from "@ariakit/utils";
import type {
  ElementType,
  FocusEvent,
  KeyboardEventHandler,
  KeyboardEvent as ReactKeyboardEvent,
  RefObject,
} from "react";
import { useEffect, useRef } from "react";
import type { FocusableOptions } from "../focusable/focusable.tsx";
import { useFocusable } from "../focusable/focusable.tsx";
import { getMoveRequest } from "./__move-request.ts";
import {
  CompositeScopedContextProvider,
  useCompositeProviderContext,
} from "./composite-context.tsx";
import type { CompositeStore, CompositeStoreItem } from "./composite-store.ts";
import {
  findFirstEnabledItem,
  getEnabledItem,
  groupItemsByRows,
  isItem,
  ownsFocus,
  silentlyFocused,
  usePresentItem,
} from "./utils.ts";

const TagName = "div" satisfies ElementType;
type TagName = typeof TagName;
type HTMLType = HTMLElementTagNameMap[TagName];

function isGrid(items: CompositeStoreItem[]) {
  return items.some((item) => !!item.rowId);
}

function isPrintableKey(event: KeyboardEvent | ReactKeyboardEvent): boolean {
  const target = event.target as Element | null;
  if (target && !isTextField(target)) return false;
  return event.key.length === 1 && !event.ctrlKey && !event.metaKey;
}

function isModifierKey(event: KeyboardEvent | ReactKeyboardEvent) {
  return (
    event.key === "Shift" ||
    event.key === "Control" ||
    event.key === "Alt" ||
    event.key === "Meta"
  );
}

function useKeyboardEventProxy(
  store: CompositeStore,
  onKeyboardEvent?: KeyboardEventHandler,
  previousElementRef?: RefObject<HTMLElement | null>,
) {
  return useEvent((event: ReactKeyboardEvent) => {
    onKeyboardEvent?.(event);
    if (event.defaultPrevented) return;
    if (event.isPropagationStopped()) return;
    if (!isSelfTarget(event)) return;
    if (isModifierKey(event)) return;
    if (isPrintableKey(event)) return;
    const state = store.getState();
    const activeElement = getEnabledItem(store, state.activeId)?.element;
    if (!activeElement) return;
    const { view, ...eventInit } = event;
    const previousElement = previousElementRef?.current;
    // If the active item element is not the previous element, this means that
    // it hasn't been focused (for example, when using composite hover). So we
    // focus on it before firing the keyboard event.
    if (activeElement !== previousElement) {
      activeElement.focus({ preventScroll: true });
    }
    if (!fireKeyboardEvent(activeElement, event.type, eventInit)) {
      event.preventDefault();
    }
    // The event will be triggered on the composite item and then propagated up
    // to this composite element again, so we can pretend that it wasn't called
    // on this component in the first place.
    if (event.currentTarget.contains(activeElement)) {
      event.stopPropagation();
    }
  });
}

function findFirstEnabledItemInTheLastRow(items: CompositeStoreItem[]) {
  return findFirstEnabledItem(
    flatten2DArray(reverseArray(groupItemsByRows(items))),
  );
}

type PresentItem = ReturnType<typeof usePresentItem>;

/**
 * Whether `instance` may act on the store's current move. An unconsumed request
 * is available to whichever instance is around; a consumed one stays with the
 * instance that consumed it, so its own effects can still run again.
 */
function mayActOnMove(store: CompositeStore, instance: object) {
  const { consumedBy } = getMoveRequest(store);
  return !consumedBy || consumedBy === instance;
}

/**
 * Records that `instance` consumed the store's move `moves`, so no later
 * instance replays it. It is per component instance rather than per composite
 * element, because switching the `composite` prop off and on again mounts a
 * fresh instance while the element itself survives. A consumption that arrives
 * after the count has moved on is dropped, resets included, because it settles
 * the request the count held when it started.
 */
function consumeMove(store: CompositeStore, instance: object, moves: number) {
  if (store.getState().moves !== moves) return;
  getMoveRequest(store).consumedBy = instance;
}

interface CompositeFocusOnMoveProps {
  store: CompositeStore;
  focusOnMove?: boolean;
  previousElementRef: RefObject<HTMLElement | null>;
  present: PresentItem;
  scrollIntoView?: (element: HTMLElement) => void;
}

/**
 * Renders nothing and reacts to the `moves` state by focusing on the active
 * item. This lives in a separate memoized component so moving through items
 * doesn't re-render the whole composite component, and composite re-renders
 * don't re-render this component. It's only rendered when the `composite` prop
 * is enabled, so this render-driving subscription doesn't run for non-composite
 * widgets. The store hook tracks move requests separately.
 */
const CompositeFocusOnMove = memo(function CompositeFocusOnMove({
  store,
  focusOnMove,
  previousElementRef,
  present,
  scrollIntoView,
}: CompositeFocusOnMoveProps) {
  const moves = useStoreState(store, "moves");
  // The composite element is also tracked so the move-to-container effect below
  // can run once it becomes available. It's published to the store through a
  // ref callback and a transaction effect on the parent composite component,
  // which run after this child component's effects. Without this dependency,
  // the effect could read a not-yet-published composite element and never
  // retry, for example when the `composite` prop switches from `false` to
  // `true` after a `move(null)` call. The composite element rarely changes, so
  // this doesn't add renders while navigating.
  const compositeElement = useStoreState(store, "compositeElement");
  // Identifies this instance to the store's move request. A ref survives the
  // effect re-runs of the same instance, including StrictMode's double
  // invocation, but not a remount, which is exactly the distinction the request
  // needs.
  const instanceRef = useRef({});

  // Present the active item.
  useEffect(() => {
    const moveRequest = getMoveRequest(store);
    if (!moves) return;
    if (!focusOnMove) return;
    const instance = instanceRef.current;
    if (!mayActOnMove(store, instance)) return;
    const { activeId } = store.getState();
    if (activeId == null) return;
    if (activeId !== moveRequest.targetId) return;
    // A programmatic move made while focus is already outside keeps its
    // focusOnMove behavior. If focus starts inside, the presentation is
    // abandoned once the user moves it elsewhere.
    return present({
      id: activeId,
      requireFocus: ownsFocus(store),
      focus: true,
      scrollIntoView,
      onConsume: () => consumeMove(store, instance, moves),
    });
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- store invalidation signal
  }, [store, moves, focusOnMove, compositeElement, present, scrollIntoView]);

  // If composite.move(null) has been called, the composite container should
  // receive focus.
  useSafeLayoutEffect(() => {
    const moveRequest = getMoveRequest(store);
    if (!moves) return;
    if (!compositeElement) return;
    const instance = instanceRef.current;
    if (!mayActOnMove(store, instance)) return;
    const { activeId } = store.getState();
    const isSelfActive = activeId === null;
    if (!isSelfActive) return;
    if (activeId !== moveRequest.targetId) return;
    // This branch has nothing left to wait for, so it consumes the request here
    // rather than reporting back the way a presentation does.
    consumeMove(store, instance, moves);
    const previousElement = previousElementRef.current;
    // We have to clean up the previous element ref so an additional blur event
    // is not fired on it, for example, when looping through items while
    // compositeElementInFocusOrder is true.
    previousElementRef.current = null;
    if (previousElement) {
      // We fire a blur event on the previous active item before moving focus to
      // the composite element so the events are dispatched in the right order
      // (blur, then focus).
      fireBlurEvent(previousElement, { relatedTarget: compositeElement });
    }
    if (!hasFocus(compositeElement)) {
      // Scroll before focusing, so a focus handler that presents something else
      // scrolls last and wins. Only for a target that can actually take focus:
      // the focus call below is a no-op for an unfocusable composite, and
      // moving the page to an element that never receives focus is the movement
      // this is meant to replace, not emulate.
      if (isFocusable(compositeElement)) {
        compositeElement.scrollIntoView({
          block: "nearest",
          inline: "nearest",
        });
      }
      compositeElement.focus({ preventScroll: true });
    }
  }, [store, moves, compositeElement, previousElementRef]);

  return null;
});

/**
 * Returns props to create a `Composite` component.
 * @see https://ariakit.com/components/composite
 * @example
 * ```jsx
 * const store = useCompositeStore();
 * const props = useComposite({ store });
 * <Role {...props}>
 *   <CompositeItem>Item 1</CompositeItem>
 *   <CompositeItem>Item 2</CompositeItem>
 * </Role>
 * ```
 */
export const useComposite = createHook<TagName, CompositeOptions>(
  function useComposite({
    store,
    composite = true,
    focusOnMove = composite,
    moveOnKeyPress = true,
    unstable_scrollIntoView: scrollIntoView,
    ...props
  }) {
    const context = useCompositeProviderContext();
    store = store || context;

    invariant(
      store,
      process.env.NODE_ENV !== "production" &&
        "Composite must receive a `store` prop or be wrapped in a CompositeProvider component.",
    );

    const ref = useRef<HTMLType>(null);
    const previousElementRef = useRef<HTMLElement | null>(null);
    const present = usePresentItem(store);

    const [, setCompositeElement] = useTransactionState(
      composite ? store.setCompositeElement : null,
    );

    const virtualFocus = useStoreState(store, "virtualFocus");
    // Only track the activeId state when composite and virtual focus are
    // enabled. It's shared by the effect below and aria-activedescendant, both
    // of which are no-ops otherwise, so this avoids re-rendering the composite
    // component on every active item change when moving through items with
    // roving tabindex.
    const activeId = useStoreState(
      store,
      composite && virtualFocus ? ["activeId"] : [],
      (state) => (composite && virtualFocus ? state.activeId : null),
    );

    // At this point, if the activeId has changed and we still have a
    // previousElement, this means that the previousElement hasn't been blurred,
    // so we do it here. This will be the scenario when moving through items, in
    // which case the onFocusCapture below event will stop propagation.
    useSafeLayoutEffect(() => {
      if (!store) return;
      if (!composite) return;
      if (!virtualFocus) return;
      const previousElement = previousElementRef.current;
      previousElementRef.current = null;
      if (!previousElement) return;
      const activeElement = getEnabledItem(store, activeId)?.element;
      const relatedTarget = activeElement || getActiveElement(previousElement);
      if (relatedTarget === previousElement) return;
      fireBlurEvent(previousElement, { relatedTarget });
    }, [store, activeId, virtualFocus, composite]);

    const onKeyDownCapture = useKeyboardEventProxy(
      store,
      props.onKeyDownCapture,
      previousElementRef,
    );

    const onKeyUpCapture = useKeyboardEventProxy(
      store,
      props.onKeyUpCapture,
      previousElementRef,
    );

    const onFocusCaptureProp = props.onFocusCapture;

    const onFocusCapture = useEvent((event: FocusEvent<HTMLType>) => {
      onFocusCaptureProp?.(event);
      if (event.defaultPrevented) return;
      if (!store) return;
      const { virtualFocus } = store.getState();
      if (!virtualFocus) return;
      const previousActiveElement = event.relatedTarget as HTMLElement | null;
      const isSilentlyFocused = silentlyFocused(event.currentTarget);
      if (isSelfTarget(event) && isSilentlyFocused) {
        // Composite has been focused as a result of an item receiving focus.
        // The composite item will move focus back to the composite container.
        // In this case, we don't want to propagate this additional event nor
        // call the onFocus handler passed to <Composite onFocus={...} />.
        event.stopPropagation();
        // We keep track of the previous active item element so we can manually
        // fire a blur event on it later when the focus is moved to another item
        // on the onBlurCapture event below.
        previousElementRef.current = previousActiveElement;
      }
    });

    const onFocusProp = props.onFocus;

    const onFocus = useEvent((event: FocusEvent<HTMLType>) => {
      onFocusProp?.(event);
      if (event.defaultPrevented) return;
      if (!composite) return;
      if (!store) return;
      const { relatedTarget } = event;
      const { virtualFocus } = store.getState();
      if (virtualFocus) {
        // This means that the composite element has been focused while the
        // composite item has not. For example, by clicking on the composite
        // element without touching any item, or by tabbing into the composite
        // element. In this case, we want to trigger focus on the item, just
        // like it would happen with roving tabindex. When it receives focus,
        // the composite item will move focus back to the composite element.
        if (isSelfTarget(event) && !isItem(store, relatedTarget)) {
          // By queueing a microtask, we make sure this runs after all the other
          // effects that might have changed the active item. This also accounts
          // for when the composite container is focused right after it gets
          // mounted (for example, in a dialog), in which case state.items will
          // not be populated yet.
          queueMicrotask(() =>
            present({
              focus: true,
              markedOnly: true,
              requireFocus: true,
              scrollIntoView,
            }),
          );
        }
      } else if (isSelfTarget(event)) {
        if (!isItem(store, relatedTarget)) {
          // A real-focus composite may initially focus the composite element
          // while the item marked as its presentation target is outside the
          // viewport. Bring that item into view without moving DOM focus away
          // from the composite element. The id is pinned because the active
          // item is cleared right below.
          const { activeId } = store.getState();
          if (activeId != null) {
            present({
              id: activeId,
              markedOnly: true,
              requireFocus: true,
              scrollIntoView,
            });
          }
        }
        // When the roving tabindex composite gets intentionally focused (for
        // example, by clicking directly on it, and not on an item), we make
        // sure to set the activeId to null (which means the composite element
        // itself has focus).
        store.setActiveId(null);
      }
    });

    const onBlurCaptureProp = props.onBlurCapture;

    const onBlurCapture = useEvent((event: FocusEvent<HTMLType>) => {
      onBlurCaptureProp?.(event);
      if (event.defaultPrevented) return;
      if (!store) return;
      const { virtualFocus, activeId, compositeElement } = store.getState();
      if (!virtualFocus) return;
      if (event.currentTarget !== compositeElement) return;
      // When virtualFocus is set to true, we move focus from the composite
      // container (this element) to the composite item that is being selected.
      // Then we move focus back to the composite container. This is so we can
      // provide the same API as the roving tabindex method, which means people
      // can attach onFocus/onBlur handlers on the CompositeItem component
      // regardless of whether virtualFocus is set to true or false. This
      // sequence of blurring and focusing on items and on the composite element
      // may be confusing, so we ignore intermediate focus and blur events by
      // stopping their propagation.
      const activeElement = getEnabledItem(store, activeId)?.element;
      const nextActiveElement = event.relatedTarget;
      const nextActiveElementIsItem = isItem(store, nextActiveElement);
      const previousElement = previousElementRef.current;
      previousElementRef.current = null;
      // This is an intermediate blur event: blurring the composite container to
      // focus on an item (nextActiveElement).
      if (isSelfTarget(event) && nextActiveElementIsItem) {
        // The next active element will be the same as the active item in the
        // store in these two scenarios:
        // - Moving focus with keyboard: the state is updated before the blur
        //   event is triggered, so here the active item is already pointing to
        //   the next active element.
        // - Clicking on the active item with a pointer: this will trigger blur
        //   on the composite element and then the next active element will be
        //   the same as the active item. Clicking on an item other than the
        //   active one doesn't end up here as the activeItem state will be
        //   updated only after that.
        if (nextActiveElement === activeElement) {
          // If there's a previous active item and it's not a click action, then
          // we fire a blur event on it so it will work just like if it had DOM
          // focus before (like when using roving tabindex).
          if (previousElement && previousElement !== nextActiveElement) {
            fireBlurEvent(previousElement, event);
          }
        }

        // This will be true when the next active element is not the active
        // element, but there's an active item. This will only happen when
        // clicking with a pointer on a different item, when there's already an
        // item selected, in which case activeElement is the item that is
        // getting blurred, and nextActiveElement is the item that is being
        // clicked.
        else if (activeElement) {
          fireBlurEvent(activeElement, event);
        }

        // TODO: Add coverage for composed-store keyboard blur.
        // Composed stores can move by keyboard before state updates; use the
        // previous element for the blur event.
        else if (previousElement) {
          fireBlurEvent(previousElement, event);
        }
        // We want to ignore intermediate blur events, so we stop the
        // propagation of this event.
        event.stopPropagation();
      } else {
        const targetIsItem = isItem(store, event.target);
        // If target is not a composite item, it may be the composite element
        // itself (isSelfTarget) or a tabbable element inside the composite
        // element. This may be triggered by clicking outside of the composite
        // element or by tabbing out of it. In either cases, we want to fire a
        // blur event on the active item.
        if (!targetIsItem && activeElement) {
          fireBlurEvent(activeElement, event);
        }
      }
    });

    const onKeyDownProp = props.onKeyDown;
    const moveOnKeyPressProp = useBooleanEvent(moveOnKeyPress);

    const onKeyDown = useEvent((event: ReactKeyboardEvent<HTMLType>) => {
      onKeyDownProp?.(event);
      // https://github.com/ariakit/ariakit/issues/4388
      if (event.nativeEvent.isComposing) return;
      if (event.defaultPrevented) return;
      if (!store) return;
      if (!isSelfTarget(event)) return;
      const { orientation, items, renderedItems, activeId, rtl } =
        store.getState();
      const activeItem = getEnabledItem(store, activeId);
      if (activeItem?.element?.isConnected) return;
      const elementlessActiveItem = activeItem && activeId != null;
      const movementItems = elementlessActiveItem ? items : renderedItems;
      const isVertical = orientation !== "horizontal";
      const isHorizontal = orientation !== "vertical";
      const grid = isGrid(movementItems);
      // If the event is coming from a text field and no item is selected,
      // horizontal keys should perform their default action on the text field
      // instead of moving focus to an item.
      const isHorizontalKey =
        event.key === "ArrowLeft" ||
        event.key === "ArrowRight" ||
        event.key === "Home" ||
        event.key === "End";
      if (isHorizontalKey && isTextField(event.currentTarget)) return;
      const up = () => {
        if (elementlessActiveItem) {
          return store.up({ activeId, renderedItems: movementItems });
        }
        if (grid) {
          const item = findFirstEnabledItemInTheLastRow(renderedItems);
          return item?.id;
        }
        return store?.last();
      };
      const right = () => {
        if (elementlessActiveItem) {
          return store.next({ activeId, renderedItems: movementItems });
        }
        return rtl ? store.last() : store.first();
      };
      const down = () => {
        if (elementlessActiveItem) {
          return store.down({ activeId, renderedItems: movementItems });
        }
        return store.first();
      };
      const left = () => {
        if (elementlessActiveItem) {
          return store.previous({ activeId, renderedItems: movementItems });
        }
        return rtl ? store.first() : store.last();
      };
      const keyMap = {
        ArrowUp: (grid || isVertical) && up,
        ArrowRight: (grid || isHorizontal) && right,
        ArrowDown: (grid || isVertical) && down,
        ArrowLeft: (grid || isHorizontal) && left,
        Home: store.first,
        End: store.last,
        PageUp: store.first,
        PageDown: store.last,
      };
      const action = keyMap[event.key as keyof typeof keyMap];
      if (action) {
        const id = action();
        if (id !== undefined) {
          if (!moveOnKeyPressProp(event)) return;
          event.preventDefault();
          store.move(id);
        }
      }
    });

    props = useWrapElement(
      props,
      (element) => (
        <CompositeScopedContextProvider value={store}>
          {element}
          {composite && (
            <CompositeFocusOnMove
              store={store}
              focusOnMove={focusOnMove}
              previousElementRef={previousElementRef}
              present={present}
              scrollIntoView={scrollIntoView}
            />
          )}
        </CompositeScopedContextProvider>
      ),
      [store, composite, focusOnMove, present],
    );

    const activeDescendant = useStoreState(
      store,
      composite && virtualFocus ? ["items"] : [],
      () => {
        if (!store) return;
        if (!composite) return;
        if (!virtualFocus) return;
        return getEnabledItem(store, activeId)?.id;
      },
    );

    props = {
      "aria-activedescendant": activeDescendant,
      ...props,
      ref: useMergeRefs(ref, setCompositeElement, props.ref),
      onKeyDownCapture,
      onKeyUpCapture,
      onFocusCapture,
      onFocus,
      onBlurCapture,
      onKeyDown,
    };

    const focusable = useStoreState(
      store,
      composite && !virtualFocus ? ["activeId"] : [],
      (state) => composite && (virtualFocus || state.activeId === null),
    );

    props = useFocusable({ focusable, ...props });

    return props;
  },
);

/**
 * Renders a composite widget.
 * @see https://ariakit.com/components/composite
 * @example
 * ```jsx
 * const composite = useCompositeStore();
 * <Composite store={composite}>
 *   <CompositeItem>Item 1</CompositeItem>
 *   <CompositeItem>Item 2</CompositeItem>
 * </Composite>
 * ```
 */
export const Composite = forwardRef(function Composite(props: CompositeProps) {
  const htmlProps = useComposite(props);
  return createElement(TagName, htmlProps);
});

export interface CompositeOptions<
  T extends ElementType = TagName,
> extends FocusableOptions<T> {
  /**
   * Object returned by the
   * [`useCompositeStore`](https://ariakit.com/reference/use-composite-store)
   * hook. If not provided, the closest
   * [`CompositeProvider`](https://ariakit.com/reference/composite-provider)
   * component's context will be used.
   */
  store?: CompositeStore;
  /**
   * Determines how an item is scrolled into view when it's presented.
   * @deprecated
   * @private
   */
  unstable_scrollIntoView?: (element: HTMLElement) => void;
  /**
   * Determines if the component should act as a composite widget. This prop
   * needs to be set to `false` when merging various composite widgets where
   * only one should function in that manner.
   *
   * If `false`, this component disables its
   * [`focusOnMove`](https://ariakit.com/reference/composite#focusonmove)
   * behavior and stops applying composite ARIA attributes. Another composite
   * component should take over these responsibilities.
   *
   * Keyboard navigation on items remains active and can still change the active
   * item. To disable arrow-key navigation, set
   * [`moveOnKeyPress`](https://ariakit.com/reference/composite#moveonkeypress)
   * to `false` on this component and its items.
   *
   * **Note**: In most cases, this prop doesn't need to be set manually. For
   * example, when composing [Menu with
   * Combobox](https://ariakit.com/examples/menu-combobox) or [Select with
   * Combobox](https://ariakit.com/examples/select-combobox), this prop will be
   * set to `false` automatically on the
   * [`Menu`](https://ariakit.com/reference/menu) and
   * [`SelectPopover`](https://ariakit.com/reference/select-popover) components
   * so the [`Combobox`](https://ariakit.com/reference/combobox) component can
   * take over the composite widget responsibilities.
   *
   * Live examples:
   * - [Menu with Combobox](https://ariakit.com/examples/menu-combobox)
   * - [Select with Combobox](https://ariakit.com/examples/select-combobox)
   * @default true
   */
  composite?: boolean;
  /**
   * Determines whether the composite widget should move focus to an item when
   * arrow keys are pressed, given that the composite element is focused and
   * there's no active item.
   *
   * **Note**: To control automatic focus movement when navigating through
   * items, use the
   * [`focusOnMove`](https://ariakit.com/reference/composite#focusonmove) prop
   * instead. If you want to control the behavior _only when arrow keys are
   * pressed_, where
   * [`focusOnMove`](https://ariakit.com/reference/composite#focusonmove) may
   * not be applicable, this prop must be set on composite items as well.
   * @default true
   * @example
   * ```jsx
   * <Composite moveOnKeyPress={false}>
   *   <CompositeItem moveOnKeyPress={false} />
   *   <CompositeItem moveOnKeyPress={false} />
   * </Composite>
   * ```
   */
  moveOnKeyPress?: BooleanOrCallback<ReactKeyboardEvent<HTMLElement>>;
  /**
   * Determines if the active composite item should receive focus (or virtual
   * focus if the
   * [`virtualFocus`](https://ariakit.com/reference/composite-provider#virtualfocus)
   * option is enabled) when moving through items. This typically happens when
   * navigating through items with arrow keys, but it can also happen when
   * calling the
   * [`move`](https://ariakit.com/reference/use-composite-store#move) method
   * directly.
   *
   * Disabling this option doesn't disable keyboard navigation or other
   * composite behavior, such as applying composite ARIA attributes.
   *
   * **Note**: If you want to control the behavior only _when arrow keys are
   * pressed_, use the
   * [`moveOnKeyPress`](https://ariakit.com/reference/composite#moveonkeypress)
   * prop instead.
   * @default true
   */
  focusOnMove?: boolean;
  /**
   * Determines whether [Focusable](https://ariakit.com/components/focusable)
   * features are active on the composite element.
   *
   * When the store's
   * [`virtualFocus`](https://ariakit.com/reference/composite-provider#virtualfocus)
   * state is `true`, the rendered composite element must remain focusable so it
   * can own DOM focus and expose the active item through
   * `aria-activedescendant`.
   *
   * @see https://ariakit.com/reference/focusable
   */
  focusable?: FocusableOptions<T>["focusable"];
}

export type CompositeProps<T extends ElementType = TagName> = Props<
  T,
  CompositeOptions<T>
>;
